<?php use app\services\Ui;use yii\helpers\Html;$this->title='Baholash davrlari';$v=fn($key,$default='')=>Yii::$app->request->post($key,$edit[$key]??$default); ?>
<div class="page-heading"><div><span class="eyebrow">ADMINISTRATOR</span><h1>Baholash davrlari</h1><p>Yangi davr uchun 139 ko‘rsatkichning alohida qoida nusxasi yaratiladi.</p></div></div><section class="card"><h2><?= $edit?'Davrni tahrirlash':'Yangi baholash davri' ?></h2><?= Html::beginForm(['admin/periods','id'=>$edit['id']??null],'post',['class'=>'filters']) ?><?= Ui::input('Davr nomi','name',$v('name'),'text',['required'=>true,'placeholder'=>'Masalan: 2026-yil']) ?><?= Ui::input('Boshlanish','starts',$v('starts'),'date',['required'=>true]) ?><?= Ui::input('Tugash','ends',$v('ends'),'date',['required'=>true]) ?><label class="check"><?= Html::checkbox('closed',(bool)$v('closed',0)) ?> Davr yopilgan</label><button class="button">Saqlash</button><?= Html::endForm() ?><p class="muted">Yopiq davrda ariza yuborish, qaror berish va qoida o‘zgartirish to‘xtatiladi. Hisobotlar ochiq qoladi.</p></section><section class="card"><h2>Davrlar ro‘yxati</h2><?php if(!$rows): ?><?= Ui::empty('Birinchi baholash davrini yarating.') ?><?php else: ?><div class="table-wrap"><table><thead><tr><th>Davr</th><th>Boshlanish</th><th>Tugash</th><th>Holat</th><th></th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><b><?= Ui::h($r['name']) ?></b></td><td><?= Ui::h($r['starts']) ?></td><td><?= Ui::h($r['ends']) ?></td><td><span class="badge <?= $r['closed']?'returned':'approved' ?>"><?= $r['closed']?'Yopiq':'Ochiq' ?></span></td><td><?= Html::a('Tahrirlash',['admin/periods','id'=>$r['id']],['class'=>'text-link']) ?> · <?= Html::a('Qoidalar',['admin/rules','period'=>$r['id']],['class'=>'text-link']) ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section>
